const password = pm.environment.get('loginPassword');
if (!password) throw new Error('Hãy đặt loginPassword trong Postman Environment trước khi chạy');
// BTH2 nhận password được Base64 mã hóa trong JSON.
const encoded = CryptoJS.enc.Base64.stringify(CryptoJS.enc.Utf8.parse(password));
pm.variables.set('loginPasswordBase64', encoded);

pm.test("HTTP 200 - Đăng nhập thành công", function () {
    pm.response.to.have.status(200);
});

if (pm.response.code === 200) {
    const data = pm.response.json();

    pm.test("Response chứa JWT", function () {
        pm.expect(data.token).to.be.a("string").and.not.empty;
    });

    if (data.token) {
        pm.environment.set("jwtToken", data.token);

        pm.test("JWT đã lưu vào Environment", function () {
            pm.expect(pm.environment.get("jwtToken"))
                .to.eql(data.token);
        });
    }
}

pm.test("HTTP 201 - Tạo đơn hàng thành công", function () {
    pm.response.to.have.status(201);
});

if (pm.response.code === 201) {
    const order = pm.response.json();

    // Test 1: Kiem tra thong tin don hang
    pm.test("Đơn hàng có id, pending, items", function () {
        pm.expect(order.id).to.be.a("number");
        pm.expect(order.status).to.eql("pending");
        pm.expect(order.items).to.be.an("array").with.lengthOf(1);
    });

    // Test 2: Kiem tra tong tien
    pm.test("Tổng tiền đúng", function () {
        const price = Number(pm.variables.get("productPrice"));
        const quantity = 1;
        const expectedTotal = price * quantity;

        pm.expect(Number(order.totalAmount))
            .to.eql(expectedTotal);
    });

    // Tu dong luu ID cua don hang moi nhat
    pm.environment.set("orderId", String(order.id));

    // Luu ID chi tiet don hang cho cac test BTH4
    if (order.items.length > 0) {
        pm.environment.set(
            "baseItemId",
            String(order.items[0].id)
        );
    }

    // Hien thi trong Postman Console
    console.log("Đã lưu orderId mới:", order.id);
    console.log("Đã lưu baseItemId:",
        pm.environment.get("baseItemId"));
}

pm.test("HTTP 201 - Thêm sản phẩm thành công", () => {
    pm.response.to.have.status(201);
});

if (pm.response.code === 201) {
    const item = pm.response.json();

    pm.test("Item thuộc đúng đơn hàng", () => {
        pm.expect(Number(item.orderId)).to.eql(
            Number(pm.variables.get("orderId"))
        );
    });

    pm.test("Số lượng thêm chính xác", () => {
        pm.expect(item.quantity).to.eql(2);
    });

    pm.test("Tổng tiền item chính xác", () => {
        pm.expect(Number(item.totalPrice)).to.be.closeTo(
            Number(item.unitPrice) * item.quantity,
            0.01
        );
    });

    pm.environment.set("addedItemId", String(item.id));

    console.log("Đã lưu addedItemId:", item.id);
}

pm.test("HTTP 200 - Cập nhật item thành công", () => {
    pm.response.to.have.status(200);
});

if (pm.response.code === 200) {
    const item = pm.response.json();

    pm.test("Số lượng cập nhật đúng", () => {
        pm.expect(item.quantity).to.eql(3);
    });

    pm.test("Tổng tiền item đúng", () => {
        const expected =
            Number(item.unitPrice) * Number(item.quantity);

        pm.expect(Number(item.totalPrice))
            .to.be.closeTo(expected, 0.01);
    });

    pm.test("Đúng item cần cập nhật", () => {
        pm.expect(Number(item.id)).to.eql(
            Number(pm.variables.get("addedItemId"))
        );
    });
}

pm.test("HTTP 204 - Xóa item thành công", () => {
    pm.response.to.have.status(204);
});

pm.test("HTTP 200", () => {
    pm.response.to.have.status(200);
});

if (pm.response.code === 200) {
    const result = pm.response.json();

    pm.test("Tồn kho cập nhật chính xác", () => {
        pm.expect(result.currentQuantity).to.eql(
            result.previousQuantity + result.quantityChange
        );

        pm.expect(result.currentQuantity)
            .to.be.at.least(0);
    });
}
